void kq20_gemv_lut_rows(const void *pv, const void *tabs, float *Y, int64_t K, int64_t r0, int64_t r1) {
    const packed_t *pk = (const packed_t *)pv;
    const float *dxs = (const float *)tabs;
    const int32_t *sx = (const int32_t *)((const uint8_t *)tabs + 4 * (K / 32));
    const uint8_t *tb = (const uint8_t *)tabs + lb_toff(K);
    const __m512i zero = _mm512_setzero_si512(), k27 = _mm512_set1_epi16(27), k3 = _mm512_set1_epi16(3);
    (void)sx; (void)zero; (void)k27; (void)k3;
    const int64_t g0 = r0 / 32, g1 = (r1 + 31) / 32;
    for (int64_t g = g0; g < g1; g += 1) {
        __m512 alo0 = _mm512_setzero_ps(), ahi0 = _mm512_setzero_ps();
        for (int64_t p = 0; p < pk->nrec_k; p++) {
                const uint8_t *rec0 = pk->buf + ((size_t)(g + 0) * pk->nrec_k + p) * REC_BYTES;
                const __m512 dlo0 = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)rec0)), dhi0 = _mm512_cvtph_ps(_mm256_loadu_si256((const __m256i *)(rec0 + 32)));
                for (int kg = 0; kg < 2; kg++) {
                    const int64_t k = p * 2 + kg;  /* unit index */
                    const uint8_t *T = tb + (size_t)k * 1408;
                    __m512i s0_0 = _mm512_setzero_si512();
                    { const __m512i W = WVEC(rec0, kg, 0);
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 0)), W, _mm512_load_si512((const void *)(T + 0 + 64))));
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 128)), _mm512_srli_epi16(W, 6), _mm512_load_si512((const void *)(T + 128 + 64))));
                    }
                    { const __m512i W = WVEC(rec0, kg, 1);
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 256)), W, _mm512_load_si512((const void *)(T + 256 + 64))));
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 384)), _mm512_srli_epi16(W, 6), _mm512_load_si512((const void *)(T + 384 + 64))));
                    }
                    { const __m512i W = WVEC(rec0, kg, 2);
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 512)), W, _mm512_load_si512((const void *)(T + 512 + 64))));
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 640)), _mm512_srli_epi16(W, 6), _mm512_load_si512((const void *)(T + 640 + 64))));
                    }
                    { const __m512i W = WVEC(rec0, kg, 3);
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 768)), W, _mm512_load_si512((const void *)(T + 768 + 64))));
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 896)), _mm512_srli_epi16(W, 6), _mm512_load_si512((const void *)(T + 896 + 64))));
                    }
                    { const __m512i W = WVEC(rec0, kg, 4);
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 1024)), W, _mm512_load_si512((const void *)(T + 1024 + 64))));
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 1152)), _mm512_srli_epi16(W, 6), _mm512_load_si512((const void *)(T + 1152 + 64))));
                    }
                    { const __m512i W = WVEC(rec0, kg, 5);
                      s0_0 = _mm512_add_epi16(s0_0, _mm512_permutex2var_epi16(_mm512_load_si512((const void *)(T + 1280)), W, _mm512_load_si512((const void *)(T + 1280 + 64))));
                    }
                    { const __m512i sv = s0_0;
                      const __m512 dx = _mm512_set1_ps(dxs[k]);
                      alo0 = fma16(lo16(sv), dlo0, dx, alo0);
                      ahi0 = fma16(hi16(sv), dhi0, dx, ahi0); }
                }
        }
        storev(Y, (g + 0) * 32, r0, r1, alo0); storev(Y, (g + 0) * 32 + 16, r0, r1, ahi0);
    }
}

void kq20_gemv_packed(const void *pv, const void *X, float *Y, int64_t K, int64_t r0, int64_t r1) {
    static __thread uint8_t *tabs;
    static __thread int64_t cap;
    int64_t bytes, units;
    kq20_gemv_lut_info(K, &bytes, &units);
    if (cap < bytes) { free(tabs); tabs = aligned_alloc(64, (size_t)(bytes + 63) & ~(size_t)63); cap = bytes; }
    kq20_gemv_lut_build(X, K, tabs, 0, units);
    kq20_gemv_lut_rows(pv, tabs, Y, K, r0, r1);
}
